dashboard.definition:
{
    "title": "Policy Management",
    "description": "Monitor access-policy coverage, change, and exceptions needing review.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h,now,auto",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,auto",
                        "label": "4h"
                    },
                    {
                        "value": "-24h,now,auto",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,auto",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,auto",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,auto",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Policy Management",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/Fingerprint.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Policy Management\nMonitor access\\-policy coverage, change, and exceptions needing review\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Policy Family Activity**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Identity  •  Zero Trust Access"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Compares selected-window ISE RADIUS and TACACS+ policy-set hit activity. Stacked columns show how each policy family contributes over time."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowTotal\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"BucketTotal\")",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "unit": " policy hits",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#f7782f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#4cbf7f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.column",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "seriesColorsByField": {
                    "RADIUS (Network Access)": "#e44273",
                    "TACACS+ (Device Admin)": "#3abdfa"
                },
                "seriesColors": [
                    "#e44273",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#9b5ff4",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "off",
                "showYMajorGridLines": false,
                "showYMinorGridLines": false,
                "xAxisTitleVisibility": "hide",
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "stackMode": "stacked",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | frameWithoutSeriesNames(\"BucketTotal\", \"WindowTotal\")"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Policy%20Family%20Activity&target=Secure%20Networking%20-%20ISE%20Policy%20Family%20Overview,Secure%20Networking%20-%20ISE%20Policy%20Hits%20by%20Network%20Device"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_01_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Policy%20Family%20Activity&target=secure_networking_zta_ise_policy_family_activity_trend"
